// ===== CONFIG — edit these =====
const TZ_OFFSET   = '+05:00'; // your timezone offset (Asia/Karachi = +05:00)
const GRACE_HOURS = 6;        // skip posts overdue by more than this (avoids backlog dump)
// ================================

const PLATFORM_MAP = {
  linkedin: 'linkedin', instagram: 'instagram',
  x: 'twitter', twitter: 'twitter',
  facebook: 'facebook', youtube: 'youtube'
};
const REQUIRES_MEDIA = new Set(['instagram', 'youtube']);

function parseTime(t) {
  const m = String(t || '').trim().match(/(\d{1,2}):(\d{2})\s*(AM|PM)?/i);
  if (!m) return null;
  let h = parseInt(m[1], 10); const min = parseInt(m[2], 10);
  const ap = (m[3] || '').toUpperCase();
  if (ap === 'PM' && h < 12) h += 12;
  if (ap === 'AM' && h === 12) h = 0;
  return { h, min };
}
function parseDate(d) {
  const s = String(d || '').slice(0, 10);
  return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null;
}

const now = Date.now();
const out = [];
for (const item of items) {
  const r = item.json;
  if (String(r['Status'] || '').trim().toLowerCase() !== 'scheduled') continue;

  const dateStr = parseDate(r['Date']);
  const tm = parseTime(r['Scheduled Time']);
  if (!dateStr || !tm) continue;

  const iso = `${dateStr}T${String(tm.h).padStart(2, '0')}:${String(tm.min).padStart(2, '0')}:00${TZ_OFFSET}`;
  const due = Date.parse(iso);
  if (isNaN(due) || due > now || due < now - GRACE_HOURS * 3600000) continue;

  const platform = PLATFORM_MAP[String(r['Platform'] || '').trim().toLowerCase()];
  if (!platform) continue;

  const caption = String(r['Caption Preview'] || '').trim();
  const tags = String(r['Hashtags'] || '').trim();
  const post = tags ? `${caption}\n\n${tags}` : caption;
  const mediaUrl = String(r['Media URL'] || '').trim();

  if (REQUIRES_MEDIA.has(platform) && !mediaUrl) {
    out.push({ json: { _skip: true, rowId: r['#'], reason: `Missing Media URL for ${platform}` } });
    continue;
  }

  const body = { post, platforms: [platform] };
  if (mediaUrl) body.mediaUrls = [mediaUrl];
  if (platform === 'youtube') body.youTubeOptions = { title: String(r['Topic'] || 'Exzelon').slice(0, 95), visibility: 'public' };

  out.push({ json: { _skip: false, rowId: r['#'], platform, ayrshareBody: body } });
}
return out;
